def IsFinitePolyhedron {d : ℕ} (K : Set (Fin d → ℝ)) : Prop :=
  ∃ n : ℕ, ∃ a : Fin n → (Fin d → ℝ), ∃ b : Fin n → ℝ,
    K = {x | ∀ j, b j ≤ dot (a j) x}

def DeterministicRankOneSigning : Prop :=
  ∃ M : Machine, ∃ C degree : ℕ, 0 < C ∧
    ∀ x : Input, Admissible x →
      let result := M.run x.encode (C * (x.length + 1) ^ degree)
      result.state = none ∧ GoodOutput x (result.stacks M.outputStack)

def Covers {ι : Type u} {M : ℕ} (A B : Set (RealSpace ι))
    (centers : Fin M → RealSpace ι) : Prop :=
  ∀ x ∈ A, ∃ j, x - centers j ∈ B

def ScalarCentralizer (S : StandardModularData H) : Prop :=
  ∀ a : H →L[ℂ] H, a ∈ S.M → (∀ t : ℝ, S.sigma t a = a) →
    ∃ c : ℂ, a = c • (1 : H →L[ℂ] H)

def SobolevOn (u : Plane → ℝ) (m : Plane → Plane) (U : Set Plane) : Prop :=
  MemLp u 2 (volume.restrict U) ∧ MemLp m 2 (volume.restrict U) ∧
    HasWeakGradientOn u m U

def IsCompactComparison (p q : Pair) (V : Set Plane) : Prop :=
  CompactlyContained
    ((q.K ∆ p.K) ∪ essentialSupport (fun x => q.u x - p.u x)) V

def Reduced (Ω K : Set Plane) : Prop :=
  K ⊆ Ω ∧ ∀ x ∈ Ω, x ∈ K ↔
    ∀ r : ℝ, 0 < r → lengthMeasure (K ∩ ball x r) ≠ 0

def Rectifiable (H : Set Plane) : Prop :=
  ∃ γ : ℕ → ℝ → Plane, (∀ n, ∃ C : ℝ≥0, LipschitzWith C (γ n)) ∧
    lengthMeasure (H \ ⋃ n, Set.range (γ n)) = 0

def InteriorArcModel (K W : Set Plane) (x : Plane) (α : ℝ) : Prop :=
  ∃ γ : ℝ → Plane, RegularHolderArc α (-1) 1 γ ∧
    γ 0 = x ∧ K ∩ W = γ '' Ioo (-1 : ℝ) 1

def EndpointArcModel (K W : Set Plane) (x : Plane) (α : ℝ) : Prop :=
  ∃ γ : ℝ → Plane, RegularHolderArc α 0 1 γ ∧
    γ 0 = x ∧ K ∩ W = γ '' Ico (0 : ℝ) 1

def IsHadamard (H : CMatrix) : Prop :=
  (∀ i j, Complex.normSq (H i j) = 1) ∧
  H.conjTranspose * H = (6 : ℂ) • (1 : CMatrix)

def IsMUBFamily {n : ℕ} (B : Fin n → Basis) : Prop :=
  ∀ r s, r ≠ s → ∀ i j,
    Complex.normSq (inner ℂ (B r i) (B s j)) = (1 : ℝ) / 6

def IsNuclear (B : Type u) [NonUnitalCStarAlgebra B] : Prop :=
  ∀ (C : Type v) [NonUnitalCStarAlgebra C] (x : B ⊗[ℂ] C),
    minTensorNorm.{u, v, max u v} x = maxTensorNorm.{u, v, max u v} x

def GlobalUpper (p : ι → ℝ) : Prop :=
  ∀ (s : ι) (S : Finset ι), (∀ c ∈ S, c ≠ T.root ∧ T.parent c = s) →
    ∑ c ∈ S, p c ^ 2 ≤ p s ^ 2

def SQ (𝕜 : Type) [RCLike 𝕜] : Prop :=
  ∀ (X : Type u) [NormedAddCommGroup X] [NormedSpace 𝕜 X] [CompleteSpace X],
    (¬ FiniteDimensional 𝕜 X) → HasSeparableQuotient 𝕜 X

def HasWeakGradient (f : Plane → ℝ) (g : Plane → Plane) : Prop :=
  ∀ (φ : Plane → ℝ), ContDiff ℝ ∞ φ → HasCompactSupport φ →
    ∀ i : Fin 2, (∫ x, f x * testPartial φ i x) = -∫ x, g x i * φ x

def InW11Loc (f : Plane → ℝ) : Prop :=
  LocallyIntegrable f ∧
    ∃ g : Plane → Plane, LocallyIntegrable g ∧ HasWeakGradient f g

def RegularAnalyticBoundaryAt (U : Set ℂ) (p : ℂ) : Prop :=
  ∃ χ : ℂ → ℂ, χ 0 = p ∧ AnalyticAt ℂ χ 0 ∧ deriv χ 0 ≠ 0 ∧
    (∀ᶠ z : ℂ in 𝓝 0, χ z ∈ frontier U ↔ z.im = 0)

def RealRankZero (D : Type uD) [CStarAlgebra D] : Prop :=
  ∀ a : D, IsSelfAdjoint a → ∀ ε : ℝ, 0 < ε →
    ∃ b : D, IsSelfAdjoint b ∧ (spectrum ℂ b).Finite ∧ ‖a - b‖ < ε

def StablyFinite (A : Type uA) [CStarAlgebra A] : Prop :=
  ∀ n : ℕ, ∀ v : CStarMatrix (Fin n) (Fin n) A,
    star v*v = 1 → v*star v = 1

def GoodPoint (F G : Plane → ℂ) (z : Plane) : Prop :=
  ∀ n : ℕ, IntegrableOn (integrand F G z)
    (annulus (1 / ((n : ℝ) + 2)) ((n : ℝ) + 2))

def MainTheorem : Prop :=
  ∀ (G : Type u) [Group G] [Countable G] [TopologicalSpace G]
    [DiscreteTopology G], ¬ Amenable G → NonamenableWitness.{u, v} G

def BoundedSmooth (F : Vec → Vec) : Prop :=
  ContDiff ℝ ∞ F ∧ ∀ n : ℕ, ∃ C : ℝ, ∀ x : Vec,
    ‖iteratedFDeriv ℝ n F x‖ ≤ C

def CompactOnFiniteHorizons (s : Solution) : Prop :=
  ∀ T : ℝ, 0 ≤ T → ∃ K : Set Phase, IsCompact K ∧
    ∀ t ∈ Icc 0 T, tsupport (fun z => s.f (t, z)) ⊆ K

