def IsSymmetricConvexBody {n : ℕ} (K : Set (Position n)) : Prop :=
  IsCompact K ∧ Convex ℝ K ∧ (interior K).Nonempty ∧
    ∀ x, x ∈ K ↔ -x ∈ K

def IsEllipsoid {n : ℕ} (K : Set (Space n)) : Prop :=
  ∃ (a : Space n) (T : Space n ≃ₗ[ℝ] Space n),
    K = (fun x => a + T x) '' unitBall n

def AlgebraicallyRegularOn (U : Set BaseCoordinates) (f : BaseCoordinates → ℂ) : Prop :=
  ∀ z ∈ U, ∃ p q : BasePolynomial, baseEval q z ≠ 0 ∧
    ∀ w ∈ U, baseEval q w ≠ 0 → f w=baseEval p w/baseEval q w

def ProjectiveAlgebraicCone {N : ℕ} (C : Set (Fin N → ℂ)) : Prop :=
  ∃ equations : Set (MvPolynomial (Fin N) ℂ),
    (∀ p ∈ equations, ∃ d : ℕ, p.IsHomogeneous d) ∧
    C = {y | ∀ p ∈ equations, MvPolynomial.eval y p=0}

def IsAmple (V : AlgebraicRankTwoBundle) : Prop :=
  ∃ n : ℕ, 0 < n ∧ ∃ N : ℕ, ∃ s : Fin N → SymmetricSection V n,
    GivesClosedProjectiveEmbedding s

def HasAVR (g : SmoothMetric3) (a : ℝ) : Prop :=
  Tendsto (fun R : ℝ ↦ (g.volumeMeasure {x | g.distance 0 x < R}).toReal /
    ((volume (Metric.ball (0 : E3) 1)).toReal * R^3)) atTop (𝓝 a)

def TwoNonisometricTangentCones (g : SmoothMetric3) : Prop :=
  ∃ (Y Z : Type) (mY : MetricSpace Y) (mZ : MetricSpace Z)
    (pY : @ProperSpace Y mY.toPseudoMetricSpace) (pZ : @ProperSpace Z mZ.toPseudoMetricSpace)
    (y : Y) (z : Z),
      @IsTangentConeAtInfinity g Y mY pY y ∧
      @IsTangentConeAtInfinity g Z mZ pZ z ∧
      ¬ ∃ e : @IsometryEquiv Y Z mY.toPseudoEMetricSpace mZ.toPseudoEMetricSpace, e y = z

def IsParallelogram {E : Type*} [AddCommGroup E] [Module ℝ E] (P : Set E) : Prop :=
  ∃ c u v : E, LinearIndependent ℝ ![u, v] ∧
    P = {x | ∃ s ∈ Icc (0 : ℝ) 1, ∃ t ∈ Icc (0 : ℝ) 1,
      x = c + s • u + t • v}

def IsTriangle {E : Type*} [AddCommGroup E] [Module ℝ E] (P : Set E) : Prop :=
  ∃ c u v : E, LinearIndependent ℝ ![u, v] ∧
    P = {x | ∃ s : ℝ, ∃ t : ℝ, 0 ≤ s ∧ 0 ≤ t ∧ s + t ≤ 1 ∧
      x = c + s • u + t • v}

def HasFiniteCover (shape : Cylinder → Prop) (S : Set Space) (A : ℝ) : Prop :=
  ∃ n : ℕ, ∃ C : Fin n → Cylinder,
    (∀ i, shape (C i)) ∧ S ⊆ familySet C ∧ familyArea C ≤ A

def OpenRectangleC2 (D : Set Plane) (v : Plane → Plane) : Prop :=
  ∃ a b : Plane, (∀ i, a i < b i) ∧
    D ⊆ {p | ∀ i, p i ∈ Ioo (a i) (b i)} ∧
    ContDiffOn ℝ 2 v {p | ∀ i, p i ∈ Ioo (a i) (b i)}

def IsSquareTile (T : Set Plane) : Prop :=
  ∃ c : Plane, ∃ R : Plane ≃ₗᵢ[ℝ] Plane, ∃ a : ℝ, 0 < a ∧
    T = (fun x => c + a • R x) '' unitSquare

def FullMain : Prop :=
  HyperbolicStatement ∧ PhysicalHyperbolicStatement ∧ LogarithmicStatement ∧
  ProductCellStatement ∧ OrthogonalGridStatement ∧ NilpotentStatement ∧ SingularStatement

def IntrinsicStability (μ : Measure M) (V : M → ℝ) : Prop :=
  ∀ η : M → ℝ, IsSmoothCompactTest I η →
    (∫ x, V x * η x ^ 2 ∂μ) ≤ ∫ x, differentialEnergy I η x ∂μ

def ApproximateMidpoints (X : Type*) [MetricSpace X] : Prop :=
  ∀ x y : X, ∀ ε : ℝ, 0 < ε → ∃ z : X,
    dist x z ≤ dist x y / 2 + ε ∧ dist z y ≤ dist x y / 2 + ε

def CanonicallyCompleteInducedMetric {F : M → E7} (hF : SmoothImmersion F) : Prop :=
  letI : MetricSpace M := canonicalInducedMetricSpace hF
  CompleteSpace M

def IsSmooth (α : TwoForm X) : Prop :=
  ∀ (f : Space → X) (U : Set Space), IsOpen U →
    ContMDiffOn Model Model ∞ f U → ContDiffOn ℝ ∞ (pullback α f) U

def IsGeodesic (γ : Curve X) : Prop :=
  ∀ s t : Time,
    dist (γ s) (γ t) = |(s : ℝ) - (t : ℝ)| * dist (γ timeZero) (γ timeOne)

def IsMinimalLocalWeakUpperGradient (m : Measure X) (f D : X → ℝ) : Prop :=
  IsLocalWeakUpperGradient m f D ∧
  ∀ D' : X → ℝ, IsLocalWeakUpperGradient m f D' → ∀ᵐ x ∂m, D x ≤ D' x

def IsTestFunction (m : Measure X) (g : X → ℝ) : Prop :=
  InLaplacianDomain m g ∧ BoundedFunction g ∧ GloballyLipschitz g ∧
    Sobolev m (laplacian m g)

def IsOptimalCoupling (q : Measure (X × X)) (μ₀ μ₁ : Measure X) : Prop :=
  IsCoupling q μ₀ μ₁ ∧ ∀ q' : Measure (X × X), IsCoupling q' μ₀ μ₁ →
    QuadraticTransportCost q ≤ QuadraticTransportCost q'

def HasWeakMTW : Prop :=
  ∀ (x : M) (v : TangentSpace (model n) x), v ∈ injectivityDomain x →
    ∀ ξ η : TangentSpace (model n) x, inner ℝ ξ η = 0 → 0 ≤ mtw x v ξ η

def Adjacent (s t : Letters) : Prop :=
  ∃ (b : Fin 3) (i j : Fin 39), s = blockLetter b i ∧ t = blockLetter b j ∧
    (i.val + 1 = j.val ∨ j.val + 1 = i.val)

def Distant (s t : Letters) : Prop :=
  ∃ (b : Fin 3) (i j : Fin 39), s = blockLetter b i ∧ t = blockLetter b j ∧
    (i.val + 2 ≤ j.val ∨ j.val + 2 ≤ i.val)

def Sentinel (s t : Letters) : Prop :=
  ((s.val = 3 ∨ s.val = 4) ∧ t.val < 3) ∨
  ((t.val = 3 ∨ t.val = 4) ∧ s.val < 3)

def SideThin {V : Type u} (X : SimpleGraph V) (δ : ℕ) {x y z : V}
    (p : X.Walk x y) (q : X.Walk y z) (r : X.Walk z x) : Prop :=
  ∀ a ∈ p.support, ∃ b, (b ∈ q.support ∨ b ∈ r.support) ∧ X.dist a b ≤ δ

def RefinedBoolean : Prop := ∀ (n : ℕ) (f : Cube n → Bool)
  (ρ : ℝ), ρ ∈ Set.Icc (-1 : ℝ) 1 →
  let m := avg (sign ∘ f)
  let bound := psi (|ρ| * psiInv (H m))
  mutualInformation (boolJoint ρ f) = info (noise ρ (sign ∘ f)) ∧
  mutualInformation (boolJoint ρ f) ≤ bound ∧ bound ≤ psi |ρ| ∧
  (0 < |m| → |m| < 1 → 0 < |ρ| → bound < psi |ρ|)

def IsSignHadamard {n : ℕ} (H : RealMatrix n) : Prop :=
  (∀ i j, IsSign (H i j)) ∧
    H * H.transpose = (n : ℝ) • (1 : RealMatrix n)

def ComputableReal (r : ℝ) : Prop :=
  ∃ a : ℕ → ℚ, Computable (fun n => ((a n).num, (a n).den)) ∧
    ∀ n, |r - (a n : ℝ)| ≤ dyadicError n

def Halts (M : FiniteMachine) (w : Input M) : Prop :=
  ∃ c, Relation.ReflTransGen (fun c d => machineStep M c = some d)
    (initialConfiguration M w) c ∧ machineStep M c = none

def ComparisonClass (u : Velocity) (p : Pressure) : Prop :=
  CH 2 u ∧ C1L2 u ∧ BoundedOnFiniteSlabs u ∧
    ∃ c : ℝ → ℝ, CH 1 (fun t x => p t x - c t)

def CommonCompactSupport (U f₀ f₁ : Velocity) : Prop :=
  ∃ K : Set Space, IsCompact K ∧
    ∀ t, 0 ≤ t → ∀ x, x ∉ K → U t x = 0 ∧ f₀ t x = 0 ∧ f₁ t x = 0

def IsMaterialFlow (u : Velocity) (X : MaterialFlow) : Prop :=
  (∀ a, X 0 a = a) ∧
  ∀ a t, 0 ≤ t → HasDerivWithinAt (fun s => X s a) (u t (X t a)) (Set.Ici 0) t

def SolvesParticle (u : Field) (a : Space) (γ : ℝ → Space) : Prop :=
  γ 0 = a ∧ ∀ t : ℝ, 0 ≤ t →
    HasDerivWithinAt γ (u t (γ t)) (Set.Ici 0) t

def ComputableReal (x : ℝ) : Prop :=
  ∃ c : Program, ∀ k : ℕ, ∃ q : ℚ,
    Encodable.encode q ∈ c.eval k ∧ |x - (q : ℝ)| ≤ error k

def inPlanarChart (d : Input) (x : Plane) : Prop :=
  ∀ j, (d.chart.lower j.castSucc : ℝ) < x j ∧
    x j < (d.chart.upper j.castSucc : ℝ)

def ComputableReal (r : ℝ) : Prop :=
  ∃ code : Nat.Partrec.Code, ∀ n : ℕ, ∃ q : ℚ,
    Encodable.encode q ∈ code.eval n ∧ |r - (q : ℝ)| ≤ errorTolerance n

def SpacePeriodic {E : Type*} (f : Spacetime → E) : Prop :=
  ∀ t, 0 ≤ t → ∀ (x : Space) (k : Fin 3 → ℤ),
    f (point t (x + fun i => (k i : ℝ))) = f (point t x)

def MaterialTrajectory (u : Field) (X : ℝ → Space) : Prop :=
  X 0 = initialLabel ∧ ContinuousOn X (Set.Ici 0) ∧
  ∀ t, 0 ≤ t → HasDerivWithinAt X (u (point t (X t))) (Set.Ici 0) t

def EnergyCompetitor (u : Field Space) (p : Field ℝ) : Prop :=
  EnergyRegularity u p ∧
  ∀ T : ℝ, 0 ≤ T → ∃ C : ℝ, ∀ t ∈ Icc 0 T, ∀ x : Space, ‖u t x‖ ≤ C

def TrajectoryOn (u : Field Space) (a : Space) (T : ℝ) (γ : ℝ → Space) : Prop :=
  γ 0 = a ∧ ∀ t ∈ Icc 0 T,
    HasDerivWithinAt γ (u t (γ t)) (Icc 0 T) t

def NamesPoint (c : Program) (t : ℝ) (x : Space) : Prop :=
  ∀ n : ℕ, ∃ q : RationalPoint, Encodable.encode q ∈ c.eval n ∧
    |(q.1 : ℝ) - t| ≤ accuracy n ∧ ‖rationalVector q.2 - x‖ ≤ accuracy n

def ForceProgram (codes : ℕ × ℕ) (f : Field Space) : Prop :=
  EvaluatesMixed (Nat.Partrec.Code.ofNatCode codes.1) f ∧
  BoundsMixed (Nat.Partrec.Code.ofNatCode codes.2) f

def BoundedMixed (F : Field) : Prop :=
  ∀ a : List (Fin 4), ∃ C : ℝ, 0 ≤ C ∧
    ∀ p : SpaceTime, 0 ≤ p 0 → ‖mixedD a F p‖ ≤ C

def ZeroNearIntegers (U f : Field) : Prop :=
  ∀ n : ℤ, ∃ ε : ℝ, 0 < ε ∧ ∀ p : SpaceTime,
    0 ≤ p 0 → |p 0 - (n : ℝ)| < ε → U p = 0 ∧ f p = 0

def SeparatelySeparated {N : ℕ} (R : Fin N → Rectangle) : Prop :=
  ∀ i j, i ≠ j → ∃ δ : ℝ, 0 < δ ∧
    ∀ x ∈ (R i).carrier, ∀ y ∈ (R j).carrier, δ ≤ ‖x - y‖

def NamesReal (c : Nat.Partrec.Code) (r : ℝ) : Prop :=
  ∀ n : ℕ, ∃ q : ℚ, Encodable.encode q ∈ c.eval n ∧
    |(q : ℝ) - r| ≤ (1 / 2 : ℝ) ^ n

def NamesPoint (c : Nat.Partrec.Code) (z : SpaceTime) : Prop :=
  ∀ n : ℕ, ∃ q : Fin 4 → ℚ,
    @Encodable.encode (Fin 4 → ℚ) Encodable.finArrow q ∈ c.eval n ∧
    ‖(fun j => (q j : ℝ)) - flatten z‖ ≤ (1 / 2 : ℝ) ^ n

def IsUnion {ι : Type u} (F : ι → RelModel.{u} L) (U : RelModel.{u} L) : Prop :=
  (∀ i, IsSubstructure (F i) U) ∧
  ∀ x : U.carrier, ∃ i, x.val ∈ (F i).carrier

def TwoModels (μ : Cardinal.{u}) : Prop :=
  ∃ M N, K.objects M ∧ K.objects N ∧
    M.carrier.card = μ ∧ N.carrier.card = μ ∧ ¬ Nonempty (M.Iso N)

def incident (S : Input A) (t : S.Config) (y : S.Edge) : Prop :=
  ∃ a : S.Config, S.rel .VB t a = true ∧
    ∃ x : S.Edge, S.rel .I a x = true ∧ S.rel .EB y x = true

def consistent (S : Input A) (lambda : S.Config → Scalar) (mu : S.Edge → Scalar) : Prop :=
  ∀ (t : S.Config) (y : S.Edge), S.incident t y →
    mu y = ∑ a : S.Config, if S.rel .VB t a then lambda a * S.coefficient y a else 0

def evaluationAccepts (time space : Polynomial ℕ) (rel : R → A → A → Bool) : Prop :=
 ∃ h st, h ≤ time.eval (Fintype.card A) ∧ P.run rel h = some st ∧ P.flag st .halt ∧ P.flag st .accept ∧
   (P.occurring rel h).card ≤ space.eval (Fintype.card A)

def EvaluationDefinable (Q : ∀ {A : Type}, [Fintype A] → Input A → Prop) : Prop :=
 ∃ P : Program Symbol, ∃ time space : Polynomial ℕ,
   ∀ (A : Type) [Fintype A] (I : Input A), P.evaluationAccepts time space I.rel ↔ Q I

